import {controller} from '@github/catalyst'
import {verifiedFetch} from '@github-ui/verified-fetch'

@controller('dashboard-tab-panels')
export class DashboardTabPanelsElement extends HTMLElement {
  async tabClick(event: Event) {
    const tab = event.currentTarget as HTMLElement
    if (tab && tab.id) {
      const formData = new FormData()
      formData.set('productivity_dashboard_selected_tab', tab.id)

      await verifiedFetch('/dashboard/preferences', {
        method: 'PUT',
        body: formData,
      })
    }
  }
}
